// MCP tools for batch 52 (1-Nov-2026): special characters & typographic punctuation.
// Pure cores come from src/tools_core52.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/chars-core-52.js and
// typo-core-52.js) — one source of truth with the 20 /tools/ character pages (em-dash … unicode-characters). Stateless: no D1/R2, no fetch.
import { MGDChars, MGDTypo } from "./tools_core52.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => (structuredContent ? { content: [{ type: "text", text }], structuredContent } : { content: [{ type: "text", text }] });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const int = (x, d, lo, hi) => { const n = parseInt(x, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const TEXT_CAP = 20000;

// The page that covers a character best (falls back to the Unicode finder).
const PAGE_OF = {};
[["em-dash", "—⸺⸻"], ["en-dash", "–‒"], ["ellipsis", "…⋯⋮"], ["quotation-marks", "“”‘’„‚«»‹›\"'"], ["inch-symbol", "′″‴"], ["trademark-symbol", "™®℠"],
 ["copyright-symbol", "©℗🄯"], ["section-symbol", "§"], ["paragraph-symbol", "¶⁋❡"], ["bullet-point-symbol", "•·◦▪‣⁃∙"], ["degree-symbol", "°℃℉º˚"],
 ["math-symbols", "±×÷≠≈≤≥√∞∑∏∫∂∴∵∝∅∈∪∩⋅−²³"], ["check-mark-symbol", "✓✔☑☐☒✗✘✅❌"], ["currency-symbols", "€£¥¢$₹₩₽₺₿₱₦₫₪₴₸฿₡"], ["spanish-accents", "ñÑ¿¡"], ["ampersand", "&⅋﹠＆"]]
  .forEach(([slug, chars]) => Array.from(chars).forEach((c) => (PAGE_OF[c] = slug)));
function pageFor(ch) {
  if (PAGE_OF[ch]) return `${T}/${PAGE_OF[ch]}/`;
  const cp = ch.codePointAt(0);
  if (cp >= 0x370 && cp <= 0x3FF) return `${T}/greek-alphabet/`;
  if (/^\p{L}$/u.test(ch) && ch.normalize("NFD").length > 1 && cp < 0x2000) return `${T}/accent-marks/`;
  return `${T}/unicode-characters/`;
}
function compact(r) {
  return { char: r.char, codepoint: r.codepoint, name: r.name, block: r.block, html: r.html.named[0] || r.html.hex, html_decimal: r.html.decimal, css: r.css, js: r.js,
    utf8: r.utf8, mac: r.mac, windows_alt: r.windows.alt, word: r.windows.word, word_alt_x: r.windows.word_alt_x, linux_compose: r.linux.compose, latex: r.latex, page: pageFor(r.char) };
}
function line(r) {
  const how = [r.mac.length ? `Mac ${r.mac.join(" or ")}` : "Mac: Fn+E (Character Viewer)", r.windows.alt.length ? `Windows ${r.windows.alt.join(" or ")} (numeric keypad)` : null,
    r.windows.word ? `Word ${r.windows.word}` : null, `Word ${r.windows.word_alt_x}`, r.linux.compose.length ? `Linux ${r.linux.compose[0]}` : null].filter(Boolean).join("; ");
  return `**${r.char}** ${r.codepoint}${r.name ? " " + r.name : ""} — HTML ${r.html.named[0] || r.html.hex} (${r.html.decimal}), CSS ${r.css}, JS ${r.js}, UTF-8 ${r.utf8}${r.latex ? ", LaTeX " + r.latex : ""}. Type: ${how}. ${pageFor(r.char)}`;
}

export const TOOL_DEFS = [
  {
    name: "lookup_character",
    description: "Use when you need a special character or symbol (em dash, °, ™, ©, §, ¶, •, ✓, €, π, é, ñ, arrows, maths…) and its codes or how to type it: search by name, alias, the character itself, U+ code point or HTML entity; returns the character with Unicode name, HTML entity, CSS/JS escapes, UTF-8, Mac Option keys, Windows Alt codes, Word shortcuts, Linux Compose and LaTeX. Pass text instead to list every code point in a string (find invisible or look-alike characters). Unicode 18.0, 10k named characters.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "A name or alias ('em dash', 'degree', 'pilcrow', 'check mark'), the character ('—'), a code point ('U+2014', '2014', '&#8212;') or an entity ('&mdash;')." },
        text: { type: "string", description: "Instead of query: a string to inspect character by character (max 500 characters listed)." },
        limit: { type: "integer", minimum: 1, maximum: 25, description: "Max matches for a name search (default 5)." },
      },
    },
    annotations: RO("Character lookup"),
  },
  {
    name: "fix_typography",
    description: "Use when copy for a design, UI, website or document needs typographically correct punctuation: converts straight quotes to curly quotes for the language (25 locales: en, de, fr, es, ja…), apostrophes, -- and spaced hyphens to dashes, number ranges to en dashes, ... to …, 5'10\" to primes, 1920x1080 to ×, double spaces; leaves code, HTML tags and URLs alone. mode=straighten reverses it (for code/CSV); mode=audit only reports issues (incl. em-dash density).",
    inputSchema: {
      type: "object",
      properties: {
        text: { type: "string", description: "The text (plain, Markdown or HTML). Max 20,000 characters." },
        mode: { type: "string", enum: ["fix", "straighten", "audit"], description: "fix (default), straighten (curly → straight), audit (report only)." },
        locale: { type: "string", description: "Quote style language, e.g. en (default), en-GB, de, fr, es, it, nl, sv, pl, ru, ja, zh." },
        dash_style: { type: "string", enum: ["closed", "spaced", "en_spaced"], description: "How a dash between words is set: closed em dash (US default), spaced em dash, or spaced en dash (UK default)." },
        em_dash: { type: "string", enum: ["keep", "closed", "spaced", "en_spaced", "comma"], description: "Restyle every existing em dash (default keep)." },
        options: { type: "object", description: "Turn rules off: {quotes, dashes, ranges, ellipsis, primes, times, spaces} = false.", properties: { quotes: { type: "boolean" }, dashes: { type: "boolean" }, ranges: { type: "boolean" }, ellipsis: { type: "boolean" }, primes: { type: "boolean" }, times: { type: "boolean" }, spaces: { type: "boolean" } } },
      },
      required: ["text"],
    },
    annotations: RO("Fix typography"),
  },
];
export const NEXT52 = {
  lookup_character: "Next step: fix_typography(text) applies curly quotes, dashes and ellipses to a whole text; style_text_unicode makes fancy Unicode text.",
  fix_typography: "Next step: lookup_character(query) gives the codes and keyboard shortcuts for any character in the result.",
};

function lookup(a) {
  if (a.text != null && str(a.text, 1)) {
    const t = str(a.text, TEXT_CAP), r = MGDChars.inspect(t, 500);
    const rows = r.chars.map((c) => `| ${c.char === "|" ? "\\|" : /\s|\p{Cf}/u.test(c.char) ? "(invisible)" : c.char} | ${c.codepoint} | ${c.name || "(no name in table)"} | ${c.html} |`);
    const odd = r.chars.filter((c) => /\p{Cf}|\p{Zs}/u.test(c.char) && c.char !== " ");
    return ok(`${r.count} character(s)${r.shown < r.count ? `, first ${r.shown} listed` : ""}${odd.length ? `; ${odd.length} invisible/special space(s): ${[...new Set(odd.map((c) => c.codepoint + " " + (c.name || "")))].join(", ")}` : ""}.\n\n| char | code point | name | HTML |\n|---|---|---|---|\n${rows.join("\n")}\n\nInspector in the browser: ${T}/unicode-characters/`,
      { count: r.count, chars: r.chars });
  }
  const q = str(a.query, 200);
  if (!q.trim() && !q) return err("Pass query (a name like 'em dash', a character, U+2014 or &mdash;) or text to inspect.");
  const res = MGDChars.lookup(q, { limit: int(a.limit, 5, 1, 25) });
  if (!res.length) return ok(`0 characters match "${q}" among ${MGDChars.count().toLocaleString("en-US")} named characters (Unicode ${MGDChars.unicodeVersion().replace("Unicode ", "")}). Try another word, the character itself or a U+ code point. Browse: ${T}/unicode-characters/`, { matches: [] });
  return ok(res.map(line).join("\n\n"), { matches: res.map(compact) });
}

function typography(a) {
  const text = str(a.text, TEXT_CAP + 1);
  if (!text) return err("Pass text (the copy to fix).");
  if (text.length > TEXT_CAP) return err(`Text is over ${TEXT_CAP.toLocaleString("en-US")} characters; send it in parts.`);
  const mode = ["fix", "straighten", "audit"].includes(a.mode) ? a.mode : "fix";
  if (mode === "audit") {
    const r = MGDTypo.audit(text);
    return ok(r.issues.length ? `Typography issues:\n${r.issues.map((i) => `- ${i.count} × ${i.message}`).join("\n")}\n\nFix them with fix_typography(mode="fix"), or in the browser: ${T}/quotation-marks/` : "No typography issues found.", r);
  }
  if (mode === "straighten") {
    const r = MGDTypo.straighten(text);
    return ok(r.text, { text: r.text, changes: r.changes });
  }
  const o = Object.assign({}, a.options && typeof a.options === "object" ? a.options : {});
  for (const k of Object.keys(o)) if (!["quotes", "dashes", "ranges", "ellipsis", "primes", "times", "spaces"].includes(k)) delete o[k];
  if (a.locale) o.locale = str(a.locale, 12);
  if (["closed", "spaced", "en_spaced"].includes(a.dash_style)) o.dash_style = a.dash_style;
  if (["keep", "closed", "spaced", "en_spaced", "comma"].includes(a.em_dash)) o.em_dash = a.em_dash;
  const r = MGDTypo.fix(text, o);
  const ch = Object.entries(r.changes).filter(([, v]) => v).map(([k, v]) => `${v} ${k.replace(/_/g, " ")}`).join(", ");
  return ok(`${r.text}\n\n(${ch ? "Changed: " + ch : "No changes needed"}; quote style ${r.locale}.)`, { text: r.text, changes: r.changes, locale: r.locale });
}

const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools52Tool(name) { return NAMES.has(name); }
export async function callTools52Tool(name, a) {
  a = a || {};
  try {
    if (name === "lookup_character") return lookup(a);
    if (name === "fix_typography") return typography(a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
